#!/usr/bin/env bash
set -euo pipefail
level=""; dir=""; input=""
usage() { echo "usage: $0 -l LEVEL [-d DIR] [-i INPUT]" >&2; exit 1; }
while getopts ":l:d:i:" opt; do
  case "$opt" in
    l) level="$OPTARG" ;;
    d) dir="$OPTARG" ;;
    i) input="$OPTARG" ;;
    *) usage ;;
  esac
done
[ -n "${level}" ] || usage
echo "level=${level} dir=${dir} input=${input}"

