#!/usr/bin/env bash
set -euo pipefail
PS3="Choose an option: "
select opt in disk memory uptime quit; do
  case "$opt" in
    disk)   df -h ;;
    memory) free -h ;;
    uptime) uptime -p ;;
    quit)   break ;;
    *) echo "invalid choice" ;;
  esac
done

