#!/usr/bin/env bash
set -euo pipefail
log() {
  local level="$1"; shift
  printf '%s [%s] %s\n' "$(date '+%Y-%m-%d %H:%M:%S')" "$level" "$*"
}
log INFO "starting job"
log WARN "low disk space"
log INFO "done"

#!/usr/bin/env bash
set -euo pipefail
input=""; level=""; name=""
usage() { echo "usage: $0 -i INPUT [-l LEVEL] [-n NAME]" >&2; exit 1; }
while getopts ":i:l:n:" opt; do
  case "$opt" in
    i) input="$OPTARG" ;;
    l) level="$OPTARG" ;;
