#!/usr/bin/env bash
set -euo pipefail
verbose=0
file=""
count=10
usage() { echo "usage: $0 -f FILE [-n COUNT] [-v]" >&2; exit 1; }
while getopts ":f:n:v" opt; do
  case "$opt" in
    f) file="$OPTARG" ;;
    n) count="$OPTARG" ;;
    v) verbose=1 ;;
    *) usage ;;
  esac
done
[ -n "$file" ] || usage
[ "$verbose" -eq 1 ] && echo "reading $count lines from $file"
head -n "$count" "$file"

#!/usr/bin/env bash
set -euo pipefail
human() {
  local b=$1 units=(B K M G T) i=0
  while [ "$b" -ge 1024 ] && [ "$i" -lt 4 ]; do
    b=$((b / 1024)); i=$((i + 1))
  done
  echo "${b}${units[$i]}"
}
human "$(stat -c %s "${1:-/etc/hostname}")"

