#!/usr/bin/env bash
set -euo pipefail
domain=example.com
cat > "/etc/nginx/sites-available/$domain" <<EOF
server {
    listen 80;
    server_name $domain;
    root /var/www/$domain;
    location / {
        try_files \$uri \$uri/ =404;
    }
}
EOF
echo "wrote config for $domain"

