    listen 80;
    server_name $domain;
    root /var/www/$domain;
    location / {
        try_files \$uri \$uri/ =404;
    }
}
EOF
echo "wrote config for $domain"

#!/usr/bin/env bash
set -euo pipefail
verbose=0
file=""
count=10
usage() { echo "usage: $0 -f FILE [-n COUNT] [-v]" >&2; exit 1; }
while getopts ":f:n:v" opt; do
  case "$opt" in
    f) file="$OPTARG" ;;
    n) count="$OPTARG" ;;
    v) verbose=1 ;;
    *) usage ;;
  esac
done
[ -n "$file" ] || usage
[ "$verbose" -eq 1 ] && echo "reading $count lines from $file"
head -n "$count" "$file"

