input=""; tag=""; port=""
usage() { echo "usage: $0 -i INPUT [-t TAG] [-p PORT]" >&2; exit 1; }
while getopts ":i:t:p:" opt; do
  case "$opt" in
    i) input="$OPTARG" ;;
    t) tag="$OPTARG" ;;
    p) port="$OPTARG" ;;
    *) usage ;;
  esac
done
[ -n "${input}" ] || usage
echo "input=${input} tag=${tag} port=${port}"

