input=""; name=""; tag=""
usage() { echo "usage: $0 -i INPUT [-n NAME] [-t TAG]" >&2; exit 1; }
while getopts ":i:n:t:" opt; do
  case "$opt" in
    i) input="$OPTARG" ;;
    n) name="$OPTARG" ;;
    t) tag="$OPTARG" ;;
    *) usage ;;
  esac
done
[ -n "${input}" ] || usage
echo "input=${input} name=${name} tag=${tag}"

